const CHILD_TICKET_HANDLINGS = new Set([
  "Take Payment",
  "Escalate to support",
  "GDPR Docs",
  "Refund Flex",
]);

let grouped_pnr_child_ticket_counter = 0;

// Stitch Customer Action selections + add pnr_route
let selected_pnrs_customer_action = (transforms.selected_pnrs_customer_action || []).map(item => {
  const customerAction = ZT.getVariableValue(`customer_action_${item.pnr}`, null);

  let pnr_route = null;
  if (customerAction === "proceed") {
    pnr_route = item.proceedHandling || null;
  } else if (customerAction === "doNotProceed") {
    pnr_route = "Do Not Proceed";
  } else if (customerAction === "changes") {
    pnr_route = "Changes";
  }

  return {
    ...item,
    customerAction,
    ...(pnr_route != null && pnr_route !== "" ? { pnr_route } : {})
  };
});

ZT.setTransformData("selected_pnrs_customer_action", selected_pnrs_customer_action);

// Group PNRS:
// - proceed -> bucket by proceedHandling
// - doNotProceed -> bucket under "doNotProceed"
// - changes -> bucket under "changes"
// AND count qualifying PNRS (customerAction === "proceed" + proceedHandling in set)
const groupedMap = selected_pnrs_customer_action.reduce((acc, item) => {
  const key =
    item.customerAction === "proceed"
      ? "proceed|" + (item.proceedHandling || "unknown")
      : item.customerAction === "doNotProceed"
        ? "doNotProceed"
        : item.customerAction === "changes"
          ? "changes"
          : "other|" + (item.customerAction || "unknown");

  if (!acc[key]) acc[key] = [];
  acc[key].push(item);

  if (
    item.customerAction === "proceed" &&
    CHILD_TICKET_HANDLINGS.has(item.proceedHandling)
  ) {
    grouped_pnr_child_ticket_counter += 1;
  }

  return acc;
}, {});

const grouped_pnrs = Object.values(groupedMap);

ZT.setTransformData("grouped_pnrs", grouped_pnrs);
ZT.setTransformData("grouped_pnr_child_ticket_counter", grouped_pnr_child_ticket_counter);

// If 2+ qualifying PNRS, create child ticket
const isCreateChildTicket = grouped_pnr_child_ticket_counter > 1;
ZT.setTransformData("isCreateChildTicket", isCreateChildTicket);

